{"implementation": "def solve(case):
    import json
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        return {'edges': [], 'total_weight': 0.0}
    if not all(node in core for node in nodes):
        raise ValueError('Missing core distance for some node')
    edges_raw = []
    for u, v, d in distances:
        if u not in core or v not in core:
            raise ValueError('Node in distances not in core')
        w = max(core[u], core[v], d)
        # canonicalize undirected endpoints
        if u < v:
            edges_raw.append((w, u, v))
        else:
            edges_raw.append((w, v, u))
    edges_raw.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    edges_added = 0
    for w, u, v in edges_raw:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            edges_added += 1
            if edges_added == n - 1:
                break
    if edges_added != n - 1:
        raise ValueError('Disconnected graph - cannot form MST')
    return {'edges': mst_edges, 'total_weight': total_weight}"}
